public:
    void rotateMatrix(vector<vector<int>>& matrix) {
        int n = matrix.size();
        for(int i = 0;i < n / 2; i++){
            swap(matrix[i],matrix[n-i-1]);
        }
        for(int i=0;i<matrix.size();i++){
            for(int j=0;j<=i;j++){
                swap(matrix[j][i],matrix[i][j]);
            }
        }
    }
};
```

